package mz.bam.seeky.android;
import android.content.*;import android.database.Cursor;import java.io.*;
final class ImportReport {
    static void write(TaskStore work,String id,Writer out)throws IOException{out.write("\ufeffnumero,nome,resultado,detalhe\r\n");try(Cursor c=work.getReadableDatabase().query("items",new String[]{"seq","name","state","message"},"job=?",new String[]{id},null,null,"seq")){while(c.moveToNext())StudyImporter.record(out,c.getInt(0)+1,c.getString(1),c.getString(2),c.getString(3));}long selected=work.count(id,null),done=work.count(id,"done"),duplicate=work.count(id,"duplicate"),failed=work.count(id,"failed");out.write("\r\nseleccionados,importados,repetidos,falhados,por_processar\r\n"+selected+","+done+","+duplicate+","+failed+","+(selected-done-duplicate-failed)+"\r\n");}
    static void save(Context c,TaskStore work,String id)throws IOException{File file=new File(StudyImporter.reports(c),"task-"+id+".csv"),part=new File(file.getPath()+".part");try(Writer out=new BufferedWriter(new OutputStreamWriter(new FileOutputStream(part),"UTF-8"))){write(work,id,out);}java.nio.file.Files.move(part.toPath(),file.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);long selected=work.count(id,null),done=work.count(id,"done"),duplicate=work.count(id,"duplicate"),failed=work.count(id,"failed");String summary=selected+" seleccionados · "+(done+duplicate+failed)+" processados\n"+done+" importados · "+duplicate+" repetidos · "+failed+" falhados\n"+(selected-done-duplicate-failed)+" por processar";c.getSharedPreferences("studies",0).edit().putString("import_report",file.getName()).putString("import_summary",summary).apply();}
    private ImportReport(){}
}
